using System.Windows;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class MobileView:System.Windows.Controls.UserControl{public MobileView(){InitializeComponent();Loaded+=(_,_)=>{if(DataContext is MobileViewModel m)ApiKeyPassword.Password=m.ApiKey;};}void ShowKey_Checked(object s,RoutedEventArgs e){var show=(s as System.Windows.Controls.CheckBox)?.IsChecked==true;ApiKeyVisible.Visibility=show?Visibility.Visible:Visibility.Collapsed;ApiKeyPassword.Visibility=show?Visibility.Collapsed:Visibility.Visible;}void CopyKey_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m){System.Windows.Clipboard.SetText(m.ApiKey);System.Windows.MessageBox.Show("کلید API کپی شد.","OdinVault");}}void Save_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m)try{m.Save();}catch(Exception x){System.Windows.MessageBox.Show(x.Message,"OdinVault");}}async void Agent_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m)await m.TestAgentAsync();}async void Port_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m)await m.TestPortAsync();}}